 const card=Array.from($(ocr?'ocr-items':decision?'decisions':'manual-items').children).find(item=>item.dataset[ocr?'ocrId':decision?'decisionId':'reviewId']===draft.id);if(!card)return;
 if(draft.bookmarkBinding){const item=view.decisions.find(item=>item.id===draft.id);if(view.stale||!item||item.structural_eligible!==true||!persistentPlanCapability(item)||!sameBookmarkDraftBinding(draft.bookmarkBinding,item))return;}
 if(Array.isArray(draft.navigationDraft)&&typeof card.restoreNavigationDraft==='function')card.restoreNavigationDraft(draft.navigationDraft);
 const fields=Array.from(card.querySelectorAll('input,textarea,select')).filter(field=>field.type!=='checkbox');
  const insertion=ocr&&card.dataset.ocrInsertion;
  if(fields.length!==draft.values.length||fields.some((field,index)=>{const saved=draft.values[index];return field.disabled||field.tagName!==saved.tag||field.type!==saved.type||field.getAttribute('aria-label')!==saved.label||(field.tagName==='SELECT'&&!insertion&&!Array.from(field.children).some(option=>option.value===saved.value));}))return;
 const target=draft.fieldIndex>=0?fields[draft.fieldIndex]:Array.from(card.querySelectorAll('button')).find(button=>button.textContent===draft.action);
 if(!target||target.disabled)return;
  fields.forEach((field,index)=>{const value=draft.values[index].value;field.value=insertion&&field.tagName==='SELECT'&&!Array.from(field.children).some(option=>option.value===value)?'':value;});if(typeof card.refreshLanguageState==='function')card.refreshLanguageState();if(typeof card.refreshNavigationState==='function')card.refreshNavigationState();if(typeof card.refreshSemanticState==='function')card.refreshSemanticState();if(typeof card.refreshTableState==='function')card.refreshTableState();if(typeof card.refreshEmptyTagState==='function')card.refreshEmptyTagState();target.focus();
