  const buttons=typeof box.querySelectorAll==='function'?Array.from(box.querySelectorAll('button')):[];
  let done=false;const finish=answer=>{if(done)return;done=true;box.removeEventListener?.('close',onClose);box.removeEventListener?.('cancel',onCancel);for(const b of buttons)b.removeEventListener?.('click',onButton);if(leaveFinish===finish)leaveFinish=null;resolve(answer);};
