$('process').addEventListener('click',action(async()=>{if(!selectedFiles.length){$('process').disabled=true;throw new Error('Choose at least one PDF first.');}const ocrMode=$('new-ocr').value;if(!['off','skip','textless','redo'].includes(ocrMode))throw new Error('Choose a supported scanned-text option before processing.');if((ocrMode!=='off'||$('new-ocrmap').checked)&&!ocrAvailable)throw new Error(ocrUnavailable);const ocrProfile=ocrMode==='off'?'standard':($('new-ocr-profile').value||'standard');if(!['standard','table-lines','angles','turns'].includes(ocrProfile))throw new Error('Choose a supported scan layout before processing.');if(ocrProfile==='angles'&&ocrMode==='redo')throw new Error('For tilted or vertical text, choose the wholly scanned pages or scan-only OCR option.');if(ocrProfile==='turns'&&ocrMode==='redo')throw new Error('For pages stored sideways or upside down, choose the wholly scanned pages or scan-only OCR option.');$('process').disabled=true;notify('Sending your PDFs to the local service. Large files can take a moment.');try{const inputs=[];for(const file of selectedFiles){const response=await fetch('/api/upload',{method:'POST',headers:{'X-Review-Token':token,'Content-Type':'application/pdf','X-File-Name':encodeURIComponent(file.name)},body:file});const result=await response.json();if(!response.ok)throw new Error(result.error);inputs.push(result.id);}
 const options={language:$('new-language').value,document_kind:$('new-kind').value,ocr_mode:ocrMode,ocr_profile:ocrProfile,allow_tag_regrouping:$('new-regroup').checked,repair_source_mappings:$('new-mapping').checked,remove_cidset:$('new-cidset').checked};if($('new-ocrmap').checked)options.repair_ocr_mappings=true;if($('new-title').value.trim())options.title=$('new-title').value.trim();watch(await api('/api/process',{inputs,options}));notify('Processing started. Your originals stay unchanged.');await refreshDashboard();}finally{$('process').disabled=false;}}));
$('find-results').addEventListener('click',action(async()=>{const result=await api('/api/bundles');$('bundle-choice').replaceChildren();for(const item of result.bundles){const status=displayStatus(item.status,item.cancelled);const option=element('option',`${item.name} · ${labels[status]||status}`);option.value=item.path;$('bundle-choice').append(option);}$('existing-results').hidden=false;if(!result.bundles.length)notify('No existing results found. Choose a PDF to create one.');}));
$('import-result').addEventListener('click',action(async()=>{if(!$('bundle-choice').value)throw new Error('Choose an existing result.');const result=await api('/api/import',{path:$('bundle-choice').value});await openWorkspace(result.workspace_id);}));
$('previous-page').addEventListener('click',action(async()=>{if(pageNumber>1){pageNumber--;await renderPage();}}));$('next-page').addEventListener('click',action(async()=>{if(pageNumber<view.page_count){pageNumber++;await renderPage();}}));$('page-number').addEventListener('change',action(async()=>{const value=Number($('page-number').value);if(!Number.isInteger(value)||value<1||value>view.page_count)throw new Error('Enter a page within this document.');pageNumber=value;await renderPage();}));
$('preview-layout').addEventListener('change',()=>{$('page-grid').dataset.mode=$('preview-layout').value;});
for(const name of ['decisions','checks']){$('tab-'+name).addEventListener('click',()=>tab(name));$('tab-'+name).addEventListener('keydown',event=>{if(event.ctrlKey||event.altKey||event.metaKey||event.shiftKey)return;if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const next=event.key==='Home'?'decisions':event.key==='End'?'checks':name==='decisions'?'checks':'decisions';tab(next);$('tab-'+next).focus();}});}
$('group-choice').addEventListener('change',renderManual);$('select-group').addEventListener('click',()=>{document.querySelectorAll('[data-manual-id]:not(:disabled)').forEach(e=>e.checked=true);$('review-confirm').checked=false;});
$('show-automatic').addEventListener('change',renderGroups);
 $('show-structure').addEventListener('change',()=>{languagePanelGeneration++;renderDecisions();if(activeJob)busy(activeJob);});
 $('show-navigation').addEventListener('change',()=>{navigationPanelGeneration++;renderDecisions();if(activeJob)busy(activeJob);});
 $('show-semantic').addEventListener('change',()=>{semanticPanelGeneration++;renderDecisions();if(activeJob)busy(activeJob);});
$('show-tables').addEventListener('change',()=>{tablePanelGeneration++;renderDecisions();if(activeJob)busy(activeJob);});
