$('previous-review').addEventListener('click',action(async()=>{const id=view?.previous_review?.workspace_id;if(typeof id!=='string'||!/^[a-f0-9]{24}$/.test(id)||id===currentId||activeJob)throw new Error('The previous saved review is not available from this result.');await openWorkspace(id);}));
$('show-ocr').addEventListener('change',action(async()=>{if($('show-ocr').checked)await loadOCRPage();else{++ocrGeneration;ocrPageData=null;ocrLoading=false;$('ocr-items').replaceChildren();$('ocr-placement').hidden=true;renderOCRSummary();}}));
$('extended-ocr').addEventListener('change',action(async()=>{if(anyOCRCommand()||hasInsertionDrafts())throw new Error('Finish the OCR action and save or clear unsaved insertion fields before changing editing mode.');await loadOCRPage();}));
$('ocr-clear-drafts').addEventListener('click',action(()=>{if(activeJob||anyOCRCommand())throw new Error('Wait for the OCR action to finish before clearing local fields.');const context=workspaceAction();for(const key of ocrInsertionDrafts.keys())if(key.startsWith(currentId+':'))ocrInsertionDrafts.delete(key);renderOCRItems();renderOCRSummary();$('ocr-placement').hidden=true;if(sameWorkspace(context))$('show-ocr').focus();notify('Unsaved insertion fields cleared in this review. Saved corrections, PDFs and review notes remain unchanged.');}));
$('ocr-apply').addEventListener('click',action(async()=>{if(activeJob||view?.stale||ocrContextStale||otherDocumentDrafts()||anyOCRCommand()||hasInsertionDrafts()||view?.ocr_editor?.available!==true||!(view.ocr_editor.accepted_count>0)||view.ocr_editor.accepted_count!==view.ocr_editor.changed_count)throw new Error('Save and accept every supported OCR correction before creating a corrected copy.');const context=workspaceAction();await runOCRCommand(context,'create-copy',async()=>{const job=await api(scopedEndpoint(context,'ocr-apply'),{revision:context.revision});if(!sameWorkspace(context))return;watch(job);notify('A separate corrected source copy is being created and checked. The earlier original and saved review stay unchanged; new checks require fresh review.');});}));
$('approve-group').addEventListener('click',action(async()=>{if(!$('review-confirm').checked)throw new Error('Confirm that you reviewed the selected occurrences and their context.');const context=workspaceAction();const focus=responseFocus('group',null,'Approve selected checks');const group=view.groups.find(g=>g.id===$('group-choice').value);const ids=Array.from(document.querySelectorAll('[data-manual-id]:checked')).map(e=>e.dataset.manualId);if(!ids.length)throw new Error('Select the occurrences you reviewed.');const result=await api(scopedEndpoint(context,'group'),{revision:context.revision,group_id:group.id,member_ids:ids,membership_digest:group.membership_digest,reviewer:reviewer()});if(showResponse(context,result,focus))notify(`${ids.length} selected review checks approved. The record remains tied to this exact PDF.`);}));
for(const id of ['credential-copy-confirm','credential-copy-reviewer'])$(id).addEventListener(id==='credential-copy-confirm'?'change':'input',()=>{credentialCopyGeneration++;renderCredentialCopy();});
for(const id of ['credential-original','credential-record'])$(id).addEventListener('click',action(async()=>{
 if(activeJob||view?.stale||!view?.credential_lineage)throw new Error('Open current bound content-credentials evidence before downloading it.');
 const context=workspaceAction(),lineage=view.credential_lineage.sha256,response=await fetch(scopedEndpoint(context,id),{headers:{'X-Review-Token':token}});
 if(!response.ok){const result=await response.json();throw new Error(result.error||'The preserved record is not available.');}
 const blob=await response.blob();if(stopped||!sameWorkspace(context)||view.revision!==context.revision||view.stale||view.credential_lineage?.sha256!==lineage)return;
 const url=URL.createObjectURL(blob),link=element('a');link.href=url;link.download=id==='credential-original'?'original-with-content-credentials.pdf':'credential-lineage.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}));
$('credential-copy').addEventListener('click',action(async()=>{
 if(stopped||activeJob||credentialCopyPending||!credentialCopyCapability())throw new Error('Open an unchanged supported blocked review before creating a separate working copy.');
 if(otherDocumentDrafts()||credentialHasLocalDrafts()||hasUnsavedEmptyTagChoices()||hasInsertionDrafts()||view.ocr_editor?.changed_count||anyOCRCommand())throw new Error('Save or restore outstanding document and OCR choices before creating a separate source copy.');
 if(!$('credential-copy-confirm').checked)throw new Error('Explicitly authorize removing Content Credentials from the separate working copy.');
 const name=$('credential-copy-reviewer').value.trim();if(!name)throw new Error('Enter your name for the separate-copy consent.');
 const context=workspaceAction(),capability=view.credential_copy,binding=credentialCopyBinding,generation=credentialCopyGeneration,drafts=credentialDraftSnapshot();
 credentialCopyPending=true;renderCredentialCopy();
 try{const job=await api(scopedEndpoint(context,'credential-copy'),{revision:context.revision,source_sha256:view.source.sha256,context_sha256:capability.context_sha256,allow_remove:true,reviewer:name});
 if(stopped||!sameWorkspace(context)||activeJob||view.revision!==context.revision||credentialCopyBinding!==binding||credentialCopyGeneration!==generation||credentialDraftSnapshot()!==drafts||!credentialCopyCapability()||view.credential_copy.context_sha256!==capability.context_sha256||!$('credential-copy-confirm').checked||$('credential-copy-reviewer').value.trim()!==name)return;
 if(typeof job?.job_id!=='string'||!/^[a-f0-9]{24}$/.test(job.job_id))throw new Error('The separate-copy response did not identify a current processing job.');
 credentialCopyWatchedJob=job.job_id;watch(job);notify('A separate copy without Content Credentials is being checked with AI and OCR off. The original PDF and saved review remain unchanged. This copy receives fresh checks and no earlier approvals.');
 }catch(error){if(!stopped&&sameWorkspace(context)&&view.revision===context.revision&&credentialCopyGeneration===generation)throw error;}finally{credentialCopyPending=false;if(!stopped&&view)renderCredentialCopy();}
}));
