$('apply').addEventListener('click',action(async()=>{if(hasUnsavedEmptyTagChoices())throw new Error('Save or restore the unsaved empty-tag choices before applying accepted edits.');watch(await api(endpoint('apply'),data()));notify('Accepted edits are being applied to a new PDF. Every automated gate runs again.');}));
$('auto-load-models').addEventListener('click',action(async()=>{const result=await api('/api/models?endpoint='+encodeURIComponent($('auto-endpoint').value));$('auto-installed-models').replaceChildren(...result.models.map(item=>{const option=element('option');option.value=item.id;return option;}));$('auto-disclosure').textContent=`${result.models.length} installed models found. No model was downloaded.`;}));
$('auto-fix').addEventListener('click',action(async()=>{if(hasUnsavedEmptyTagChoices())throw new Error('Save or restore the unsaved empty-tag choices before creating another result.');const useAI=$('auto-ai').checked;if(useAI&&!$('auto-model').value.trim())throw new Error('Choose an installed local model, or leave local AI off.');autoPending=true;autoStart=Date.now();$('auto-fix').disabled=true;renderAutoPending();let started;try{started=await api(endpoint('auto-fix'),data({consent:true,use_ai:useAI,ai_consent:useAI,endpoint:$('auto-endpoint').value,model:$('auto-model').value.trim(),include_images:$('auto-images').checked,reasoning_effort:$('auto-fast').checked?'none':null}));}catch(error){autoPending=false;autoJob=null;renderAutoStatus([]);$('auto-fix').disabled=Boolean(view&&view.stale);renderCancelButtons();throw error;}
autoPending=false;autoJob=started.job_id;watch(started);renderAutoStatus([{id:started.job_id,status:'queued',progress:[]}]);renderCancelButtons();notify('Automatic mode is creating a separate checked result. Supported choices are applied without individual approvals.');}));
