$('download').addEventListener('click',action(async()=>{const response=await fetch(endpoint('download'),{headers:{'X-Review-Token':token}});if(!response.ok){const result=await response.json();throw new Error(result.error);}const url=URL.createObjectURL(await response.blob());const a=element('a');a.href=url;const suggested=/filename="([^"]+)"/.exec(response.headers.get('Content-Disposition')||'');a.download=suggested?suggested[1]:'document-candidate.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}));
