$('ask-ai').addEventListener('click',action(async()=>{const ids=Array.from(document.querySelectorAll('[data-ai-id]:checked')).map(e=>e.dataset.aiId);if(!ids.length)throw new Error('Select the descriptions or title you want help drafting.');if(!$('ai-model').value.trim())throw new Error('Choose an installed model.');if(!$('ai-consent').checked)throw new Error('Explicitly select sending the chosen context to the local model.');watch(await api(endpoint('assist'),data({endpoint:$('ai-endpoint').value,model:$('ai-model').value.trim(),decision_ids:ids,include_images:$('ai-images').checked,reasoning_effort:$('ai-fast').checked?'none':null,consent:true})));$('ai-disclosure').textContent='Only the selected decision context is being sent to the chosen local model. No draft is applied automatically.';}));
$('update-check').addEventListener('click',action(async()=>{const button=$('update-check'),out=$('update-result');if(button.disabled)return;button.disabled=true;out.textContent='Checking for a newer version...';out.hidden=false;try{const result=await api('/api/update-check');out.textContent=String(result.message||'');if(typeof result.url==='string'&&result.url.startsWith('https://github.com/')){const link=element('a',result.link_text||'Open the download page');link.href=result.url;link.target='_blank';link.rel='noopener noreferrer';out.append(link);}}catch(error){out.textContent='';out.hidden=true;throw error;}finally{button.disabled=false;}}));
